{"command":"python3 -c '
import hashlib, struct

target_basic = "e98d9238eb5b343ceb8661b78e939874148b90db64578db6e0412d48fa8d2a03"
target_fam = "5245b0db7c328e34eb3b18f06123a8fec12e471852e511b80186eed4c3021161"

def bincode_str(s):
    b = s.encode("utf-8")
    return struct.pack("<Q", len(b)) + b

q, a = "a", "b"

# Variant 1: Basic struct { question: String, answer: String }
# bincode: len(q) + q + len(a) + a
b1 = bincode_str(q) + bincode_str(a)

# Variant 2: Enum Card::Basic(String, String) or Content::Basic { question, answer }
# Enum variant index 0 (u32 or u64):
for enum_idx in [struct.pack("<I", 0), struct.pack("<Q", 0), struct.pack("<I", 1), struct.pack("<Q", 1)]:
    b2 = enum_idx + bincode_str(q) + bincode_str(a)
    for b in [b1, b2]:
        if hashlib.sha256(b).hexdigest() == target_basic:
            print("FOUND BINCODE BASIC:", b)

# Cloze family: text "a b"
b_fam1 = bincode_str("a b")
for enum_idx in [struct.pack("<I", 0), struct.pack("<Q", 0), struct.pack("<I", 1), struct.pack("<Q", 1)]:
    b_fam2 = enum_idx + bincode_str("a b")
    for b in [b_fam1, b_fam2]:
        if hashlib.sha256(b).hexdigest() == target_fam:
            print("FOUND BINCODE FAMILY:", b)

'"}

