import hashlib, json

target_basic = "e98d9238eb5b343ceb8661b78e939874148b90db64578db6e0412d48fa8d2a03"
target_fam = "5245b0db7c328e34eb3b18f06123a8fec12e471852e511b80186eed4c3021161"

# Serde representations for Basic(q="a", a="b"):
# Externally tagged enum: {"basic":{"question":"a","answer":"b"}}
# Internally tagged: {"type":"basic","question":"a","answer":"b"}
# Adjacently tagged: {"t":"basic","c":{"question":"a","answer":"b"}}
# Untagged: {"question":"a","answer":"b"}

# With camelCase, PascalCase, snake_case, UPPERCASE:
casing = ["basic", "Basic", "BASIC", "basicCard", "BasicCard"]

objs_basic = []
for c in casing:
    objs_basic.append({c: {"question": "a", "answer": "b"}})
    objs_basic.append({"type": c, "question": "a", "answer": "b"})
    objs_basic.append({"t": c, "c": {"question": "a", "answer": "b"}})
objs_basic.append({"question": "a", "answer": "b"})

for obj in objs_basic:
    for separators in [(",", ":"), (", ", ": "), (",", " : ")]:
        s = json.dumps(obj, separators=separators)
        if hashlib.sha256(s.encode()).hexdigest() == target_basic:
            print("MATCH BASIC:", repr(s))

'"}

