import hashlib

target_empty = "56fe5043651261131c9df7ded34d7f122a4fbabc5af57c6b06c92ed50ff6e6b4"
target_hello = "ae0608618ec9d578e38892e02c106ecc7fdfc9cf0e73b4400887120b9f8ccb96"

def cbor_str(s):
    b = s.encode("utf-8")
    l = len(b)
    if l < 24:
        return bytes([0x60 + l]) + b
    elif l < 256:
        return bytes([0x78, l]) + b
    else:
        return bytes([0x79, l >> 8, l & 0xff]) + b

def cbor_map(d):
    l = len(d)
    res = bytes([0xa0 + l])
    for k, v in d.items():
        res += cbor_str(k)
        if isinstance(v, str):
            res += cbor_str(v)
        elif isinstance(v, int):
            res += bytes([v])
        elif isinstance(v, dict):
            res += cbor_map(v)
    return res

# ciborium externally tagged enum: {"basic": {"question": "Hello", "answer": "World"}}
c1 = cbor_map({"basic": {"question": "Hello", "answer": "World"}})
c2 = cbor_map({"basic": {"question": "", "answer": ""}})

print("CBOR hello:", hashlib.sha256(c1).hexdigest(), "vs", target_hello)
print("CBOR empty:", hashlib.sha256(c2).hexdigest(), "vs", target_empty)
'"}

