{"command":"cat <<'EOF' > /tmp/test_proj/src/main.rs
use ciborium;
use serde::Serialize;
use sha2::{Digest, Sha256};

#[derive(Serialize, Debug)]
#[serde(rename_all = "camelCase")]
enum Content {
    Basic { question: String, answer: String },
    Cloze { text: String, start: usize, end: usize },
}

#[derive(Serialize, Debug)]
struct ClozeText {
    text: String,
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{:02x}", b)).collect()
}

fn hash_ciborium<T: Serialize>(val: &T) -> String {
    let mut buf = Vec::new();
    ciborium::into_writer(val, &mut buf).unwrap();
    let mut hasher = Sha256::new();
    hasher.update(&buf);
    hex(&hasher.finalize())
}

fn hash_json<T: Serialize>(val: &T) -> String {
    let buf = serde_json::to_vec(val).unwrap();
    let mut hasher = Sha256::new();
    hasher.update(&buf);
    hex(&hasher.finalize())
}

fn main() {
    let target_empty = "56fe5043651261131c9df7ded34d7f122a4fbabc5af57c6b06c92ed50ff6e6b4";
    let target_hello = "ae0608618ec9d578e38892e02c106ecc7fdfc9cf0e73b4400887120b9f8ccb96";
    let target_fam = "e5b219ae025541e3ae41abf5d6077a76d23d79d7bdd909f04b934811a1117892";

    let c_empty = Content::Basic { question: "".into(), answer: "".into() };
    let c_hello = Content::Basic { question: "Hello".into(), answer: "World".into() };

    println!("ciborium empty: {}", hash_ciborium(&c_empty));
    println!("target empty:   {}", target_empty);
    println!("ciborium hello: {}", hash_ciborium(&c_hello));
    println!("target hello:   {}", target_hello);

    println!("ciborium fam:   {}", hash_ciborium(&ClozeText { text: "x".into() }));
    println!("target fam:     {}", target_fam);
}
EOF

