use sha2::{Digest, Sha256};
use serde::Serialize;

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{:02x}", b)).collect()
}

fn check(name: &str, data: &[u8], target: &str) -> bool {
    let mut hasher = Sha256::new();
    hasher.update(data);
    let h = hex(&hasher.finalize());
    if h == target {
        println!("FOUND MATCH! [{}] data={:?} -> {}", name, data, h);
        true
    } else {
        false
    }
}

#[derive(Serialize)]
struct Basic1 { question: String, answer: String }

#[derive(Serialize)]
struct Basic2 { answer: String, question: String }

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
enum Content1 { Basic { question: String, answer: String } }

#[derive(Serialize)]
enum Content2 { Basic { question: String, answer: String } }

#[derive(Serialize)]
#[serde(tag = "type", rename_all = "camelCase")]
enum Content3 { Basic { question: String, answer: String } }

#[derive(Serialize)]
#[serde(untagged)]
enum Content4 { Basic { question: String, answer: String } }

#[derive(Serialize)]
struct Card1 { content: Content1 }

#[derive(Serialize)]
struct Card2 { content: Content2 }

fn main() {
    let target = "04692f67ddc4fcbe134687b0f3120ac9821c40f85676c6b06c92ed50ff6e6b4";
    let q = "foo".to_string();
    let a = "bar".to_string();

    let b1 = Basic1 { question: q.clone(), answer: a.clone() };
    let b2 = Basic2 { question: q.clone(), answer: a.clone() };
    let c1 = Content1::Basic { question: q.clone(), answer: a.clone() };
    let c2 = Content2::Basic { question: q.clone(), answer: a.clone() };
    let c3 = Content3::Basic { question: q.clone(), answer: a.clone() };
    let c4 = Content4::Basic { question: q.clone(), answer: a.clone() };

    let card1 = Card1 { content: Content1::Basic { question: q.clone(), answer: a.clone() } };
    let card2 = Card2 { content: Content2::Basic { question: q.clone(), answer: a.clone() } };

    // Ciborium
    let mut buf = Vec::new();
    let mut test_cb = |name: &str, val: &dyn erased_serde::Serialize| {
        buf.clear();
        ciborium::into_writer(val, &mut buf).ok();
        check(name, &buf, target);
    };

    // json
    let mut test_json = |name: &str, val: &dyn erased_serde::Serialize| {
        let v = serde_json::to_vec(val).unwrap();
        check(name, &v, target);
        let s = serde_json::to_string_pretty(val).unwrap();
        check(&format!("{}_pretty", name), s.as_bytes(), target);
    };

    // yaml
    let mut test_yaml = |name: &str, val: &dyn erased_serde::Serialize| {
        let s = serde_yaml::to_string(val).unwrap();
        check(name, s.as_bytes(), target);
    };

    // Let us check all
    test_cb("ciborium b1", &b1);
    test_cb("ciborium b2", &b2);
    test_cb("ciborium c1", &c1);
    test_cb("ciborium c2", &c2);
    test_cb("ciborium c3", &c3);
    test_cb("ciborium c4", &c4);
    test_cb("ciborium card1", &card1);
    test_cb("ciborium card2", &card2);

    test_json("json b1", &b1);
    test_json("json b2", &b2);
    test_json("json c1", &c1);
    test_json("json c2", &c2);
    test_json("json c3", &c3);
    test_json("json c4", &c4);
    test_json("json card1", &card1);
    test_json("json card2", &card2);

    test_yaml("yaml b1", &b1);
    test_yaml("yaml b2", &b2);
    test_yaml("yaml c1", &c1);
    test_yaml("yaml c2", &c2);
    test_yaml("yaml c3", &c3);
    test_yaml("yaml c4", &c4);
}
