import os
import re
import hashlib
from pathlib import Path

class ParseError(Exception):
    def __init__(self, message, file_path, line_no):
        super().__init__(f"hashcards: error: Parse error: {message}. Location: {file_path}:{line_no}")
        self.message = message
        self.file_path = file_path
        self.line_no = line_no

def sha256_hex(data: str) -> str:
    return hashlib.sha256(data.encode("utf-8")).hexdigest()

def compute_basic_hash(question: str, answer: str) -> str:
    return sha256_hex(f"basic:{question}\n{answer}")

def compute_cloze_family_hash(text: str) -> str:
    return sha256_hex(f"cloze_family:{text}")

def compute_cloze_hash(text: str, start: int, end: int) -> str:
    return sha256_hex(f"cloze:{text}:{start}:{end}")

def parse_clozes(raw_text):
    stripped_chars = []
    clozes = []

    i = 0
    in_cloze = False
    cloze_start_stripped = 0
    current_cloze_chars = []

    while i < len(raw_text):
        ch = raw_text[i]
        if ch == "[":
            in_cloze = True
            cloze_start_stripped = len(stripped_chars)
            current_cloze_chars = []
        elif ch == "]":
            if in_cloze:
                in_cloze = False
                cloze_end_stripped = len(stripped_chars) - 1
                clozes.append((cloze_start_stripped, cloze_end_stripped, "".join(current_cloze_chars)))
        else:
            stripped_chars.append(ch)
            if in_cloze:
                current_cloze_chars.append(ch)
        i += 1

    stripped_text = "".join(stripped_chars)
    return stripped_text, clozes

def parse_file(file_path: str):
    abs_path = os.path.abspath(file_path)
    deck_name = Path(file_path).stem

    with open(file_path, "r", encoding="utf-8", errors="replace") as f:
        lines = f.readlines()

    cards = []

    current_type = None # "Q" or "C"
    q_lines = []
    a_lines = []
    c_lines = []

    card_line_start = 0
    q_start_line_1based = 0
    c_start_line_1based = 0

    i = 0
    N = len(lines)

    while i < N:
        line = lines[i]
        stripped = line.strip()

        if line.startswith("Q:"):
            line_1based = i + 1
            if current_type == "Q":
                raise ParseError("New question without answer", abs_path, line_1based)
            elif current_type == "C":
                # Finish C
                raw_c_text = "\n".join(c_lines).strip()
                stripped_text, clozes = parse_clozes(raw_c_text)
                if not clozes:
                    raise ParseError("Cloze card must contain at least one cloze deletion", abs_path, c_start_line_1based)
                fam_hash = compute_cloze_family_hash(stripped_text)
                card_line_end = i
                for start, end, _ in clozes:
                    c_hash = compute_cloze_hash(stripped_text, start, end)
                    cards.append({
                        "hash": c_hash,
                        "familyHash": fam_hash,
                        "deckName": deck_name,
                        "location": {
                            "filePath": abs_path,
                            "lineStart": card_line_start,
                            "lineEnd": card_line_end
                        },
                        "content": {
                            "cloze": {
                                "text": stripped_text,
                                "start": start,
                                "end": end
                            }
                        }
                    })
                c_lines = []
                current_type = None

            # Start new Q
            current_type = "Q"
            card_line_start = i
            q_start_line_1based = line_1based
            q_lines = [line[2:].lstrip("\r\n").rstrip("\r\n")]
            if q_lines[0].startswith(" "):
                q_lines[0] = q_lines[0][1:]
            a_lines = []

        elif line.startswith("A:"):
            line_1based = i + 1
            if current_type != "Q":
                raise ParseError("Found answer tag without a question", abs_path, line_1based)

            current_type = "A"
            a_first = line[2:].lstrip("\r\n").rstrip("\r\n")
            if a_first.startswith(" "):
                a_first = a_first[1:]
            a_lines = [a_first]

        elif line.startswith("C:"):
            line_1based = i + 1
            if current_type == "Q":
                raise ParseError("New question without answer", abs_path, line_1based)
            elif current_type == "C":
                # Finish C
                raw_c_text = "\n".join(c_lines).strip()
                stripped_text, clozes = parse_clozes(raw_c_text)
                if not clozes:
                    raise ParseError("Cloze card must contain at least one cloze deletion", abs_path, c_start_line_1based)
                fam_hash = compute_cloze_family_hash(stripped_text)
                card_line_end = i
                for start, end, _ in clozes:
                    c_hash = compute_cloze_hash(stripped_text, start, end)
                    cards.append({
                        "hash": c_hash,
                        "familyHash": fam_hash,
                        "deckName": deck_name,
                        "location": {
                            "filePath": abs_path,
                            "lineStart": card_line_start,
                            "lineEnd": card_line_end
                        },
                        "content": {
                            "cloze": {
                                "text": stripped_text,
                                "start": start,
                                "end": end
                            }
                        }
                    })
                c_lines = []

            current_type = "C"
            card_line_start = i
            c_start_line_1based = line_1based
            c_first = line[2:].lstrip("\r\n").rstrip("\r\n")
            if c_first.startswith(" "):
                c_first = c_first[1:]
            c_lines = [c_first]

        else:
            if current_type == "Q":
                q_lines.append(line.rstrip("\r\n"))
            elif current_type == "A":
                a_lines.append(line.rstrip("\r\n"))
            elif current_type == "C":
                c_lines.append(line.rstrip("\r\n"))

            if current_type in ("A", "C"):
                # If we encounter next card or EOF, we close card.
                pass

        # Check if card finishes
        if current_type == "A":
            # Check if next line starts Q:, A:, C: or is EOF or if we keep reading A
            # Actually, A keeps reading until next Q:, C: or EOF!
            pass

        i += 1

    # End of file checks
    if current_type == "Q":
        raise ParseError("File ended while reading a question without an answer", abs_path, q_start_line_1based)

    elif current_type == "A":
        q_text = "\n".join(q_lines).strip()
        a_text = "\n".join(a_lines).strip()
        b_hash = compute_basic_hash(q_text, a_text)
        card_line_end = N
        cards.append({
            "hash": b_hash,
            "familyHash": None,
            "deckName": deck_name,
            "location": {
                "filePath": abs_path,
                "lineStart": card_line_start,
                "lineEnd": card_line_end
            },
            "content": {
                "basic": {
                    "question": q_text,
                    "answer": a_text
                }
            }
        })

    elif current_type == "C":
        raw_c_text = "\n".join(c_lines).strip()
        stripped_text, clozes = parse_clozes(raw_c_text)
        if not clozes:
            raise ParseError("Cloze card must contain at least one cloze deletion", abs_path, c_start_line_1based)
        fam_hash = compute_cloze_family_hash(stripped_text)
        card_line_end = N
        for start, end, _ in clozes:
            c_hash = compute_cloze_hash(stripped_text, start, end)
            cards.append({
                "hash": c_hash,
                "familyHash": fam_hash,
                "deckName": deck_name,
                "location": {
                    "filePath": abs_path,
                    "lineStart": card_line_start,
                    "lineEnd": card_line_end
                },
                "content": {
                    "cloze": {
                        "text": stripped_text,
                        "start": start,
                        "end": end
                    }
                }
            })

    return cards

def parse_collection(dir_path: str):
    abs_dir = os.path.abspath(dir_path)
    if not os.path.exists(abs_dir) or not os.path.isdir(abs_dir):
        raise ValueError("hashcards: error: directory does not exist.")

    md_files = []
    for root, dirs, files in os.walk(abs_dir):
        # Exclude hidden dirs
        dirs[:] = [d for d in dirs if not d.startswith(".")]
        for f in files:
            if f.endswith(".md") and not f.startswith("."):
                md_files.append(os.path.join(root, f))

    md_files.sort()

    all_cards = []
    for fpath in md_files:
        cards = parse_file(fpath)
        all_cards.extend(cards)

    # Check macros.tex
    macro_count = 0
    macros_path = os.path.join(abs_dir, "macros.tex")
    if os.path.exists(macros_path):
        with open(macros_path, "r", encoding="utf-8", errors="replace") as mf:
            lines = [l.strip() for l in mf.readlines() if l.strip()]
            macro_count = len(lines)

    return all_cards, macro_count
